// Use workerd's actual AI binding. Only replace its network transport so the
// provider responses can be recorded/replayed by the normal cassette harness.
// No model results are generated by this plugin or the transport bridge.
export const plugins = {
  workersAIRecording: {
    getBindings(bindings) {
      return bindings.map(({ name }) => ({
        name,
        wrapped: {
          moduleName: "cloudflare-internal:ai-api",
          innerBindings: [
            {
              name: "fetcher",
              service: { name: "workers-ai-recording-transport" },
            },
          ],
        },
      }));
    },
    getNodeBindings() {
      return {};
    },
    getServices({ options }) {
      return options.map(({ options: { address } }) => ({
        name: "workers-ai-recording-transport",
        external: { address, http: {} },
      }));
    },
  },
};
